fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut seed: i32 = host::display::state_get(1);
    if seed == 0 { seed = 90210; }
    if down == 1 && prev == 0 {
        seed = seed * 1103515245 + 12345;
        host::display::state_set(1, seed);
    }
    host::display::state_set(0, down);
    let cell: i32 = 24;
    let cols: i32 = w / cell;
    let rows: i32 = h / cell;
    host::display::clear(0x020803);
    let mut r: i32 = 0;
    while r < rows {
        let sweep: i32 = if ((r * 3 + t / 2) & 31) == 0 { 1 } else { 0 };
        let mut c: i32 = 0;
        while c < cols {
            let mut hsh: i32 = seed + r * 7919 + c * 104729;
            hsh = hsh * 1103515245 + 12345;
            if ((hsh >> 8) & 7) != 0 {
                let code: i32 = 33 + ((hsh >> 16) & 32767) % 94;
                let col: i32 = if sweep == 1 { 0xccffdd } else { 0x22cc55 };
                host::display::draw_char(c * cell + 4, r * cell + 4, code, col, 2);
            }
            c = c + 1;
        }
        r = r + 1;
    }
    host::display::present();
}
